#!/usr/bin/env python3
"""Compile complete microservice invocation paths into a canonical minimal DFA.

The program reads JSONL requests from standard input and writes exactly one
JSON object per input line to standard output.  Errors are reported as
{"ok": false, "error": "<CODE>"} objects and never abort the stream.

Pipeline
--------
  1. byte length / UTF-8 decoding
  2. preliminary bracket-depth scan (bounds parser nesting)
  3. JSON parsing (duplicate keys and NaN/Infinity rejected)
  4. schema validation
  5. declared size limits
  6. atomic-monitor complexity limit
  7. monitor product -> acceptance -> DFA minimisation -> canonical numbering
"""

import json
import sys
from collections import deque

# ------------------------------------------------------------------ limits

MAX_LINE_BYTES = 1048576
MAX_NEST_DEPTH = 64
MAX_SERVICES = 24
MAX_SERVICE_CHARS = 64
MAX_RULES = 32
MAX_EXPR_NODES = 256
MAX_ARGS = 32
MAX_ATOM_PATH = 16
MAX_ATOMS = 10
MAX_QUERIES = 256
MAX_QUERY_TOKENS = 4096
MAX_QUERY_TOTAL = 16384
MAX_PRODUCT_STATES = 20000

# ------------------------------------------------------------- error codes

E_JSON = "E_JSON"
E_SCHEMA = "E_SCHEMA"
E_LIMIT = "E_LIMIT"
E_COMPLEXITY = "E_COMPLEXITY"

ATOM_OPS = ("match", "startswith", "endswith", "contains")


class ReqError(Exception):
    """A request-level failure carrying one of the specified error codes."""

    __slots__ = ("code",)

    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


# --------------------------------------------------------------- utilities


def _scalar_ok(text):
    """True when every character of *text* is a Unicode scalar value."""
    try:
        text.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return True


def _depth_ok(text):
    """Preliminary bracket-depth scan; strings and escapes handled as JSON."""
    depth = 0
    index = 0
    size = len(text)
    in_string = False
    while index < size:
        char = text[index]
        if in_string:
            if char == "\\":
                index += 2
                continue
            if char == '"':
                in_string = False
        else:
            if char == '"':
                in_string = True
            elif char == "{" or char == "[":
                depth += 1
                if depth > MAX_NEST_DEPTH:
                    return False
            elif char == "}" or char == "]":
                if depth > 0:
                    depth -= 1
        index += 1
    return True


def _object_pairs(pairs):
    """json hook rejecting duplicate object keys."""
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate object key")
        result[key] = value
    return result


def _reject_constant(name):
    """json hook rejecting NaN / Infinity / -Infinity."""
    raise ValueError("forbidden numeric constant: %s" % (name,))


# -------------------------------------------------------------- validation


class _Context(object):
    """Everything derived from a validated request."""

    __slots__ = ("alphabet", "index", "atoms", "atom_index", "rules",
                 "queries", "nodes", "max_args", "max_path", "query_tokens")


def _new_context():
    ctx = _Context()
    ctx.alphabet = []
    ctx.index = {}
    ctx.atoms = []
    ctx.atom_index = {}
    ctx.rules = []
    ctx.queries = []
    ctx.nodes = 0
    ctx.max_args = 0
    ctx.max_path = 0
    ctx.query_tokens = 0
    return ctx


def _compile_expression(node, ctx):
    """Validate one expression node and compile it into a compact form."""
    ctx.nodes += 1
    if not isinstance(node, dict):
        raise ReqError(E_SCHEMA)
    keys = set(node.keys())
    op = node.get("op")
    if not isinstance(op, str):
        raise ReqError(E_SCHEMA)
    if op == "true" or op == "false":
        if keys != set(["op"]):
            raise ReqError(E_SCHEMA)
        return ("const", op == "true")
    if op in ATOM_OPS:
        if keys != set(["op", "path"]):
            raise ReqError(E_SCHEMA)
        path = node["path"]
        if not isinstance(path, list):
            raise ReqError(E_SCHEMA)
        tokens = []
        for token in path:
            if not isinstance(token, str):
                raise ReqError(E_SCHEMA)
            if not _scalar_ok(token):
                raise ReqError(E_SCHEMA)
            if token not in ctx.index:
                raise ReqError(E_SCHEMA)
            tokens.append(token)
        if len(tokens) > ctx.max_path:
            ctx.max_path = len(tokens)
        key = (op, tuple(tokens))
        atom_id = ctx.atom_index.get(key)
        if atom_id is None:
            atom_id = len(ctx.atoms)
            ctx.atom_index[key] = atom_id
            ctx.atoms.append(key)
        return ("atom", atom_id)
    if op == "not":
        if keys != set(["op", "arg"]):
            raise ReqError(E_SCHEMA)
        return ("not", _compile_expression(node["arg"], ctx))
    if op == "and" or op == "or":
        if keys != set(["op", "args"]):
            raise ReqError(E_SCHEMA)
        args = node["args"]
        if not isinstance(args, list):
            raise ReqError(E_SCHEMA)
        if len(args) > ctx.max_args:
            ctx.max_args = len(args)
        return (op, [_compile_expression(arg, ctx) for arg in args])
    raise ReqError(E_SCHEMA)


def _validate(request):
    """Full schema validation; raises ReqError on the first violation."""
    if not isinstance(request, dict):
        raise ReqError(E_SCHEMA)
    if set(request.keys()) != set(["services", "rules", "queries"]):
        raise ReqError(E_SCHEMA)

    ctx = _new_context()

    services = request["services"]
    if not isinstance(services, list):
        raise ReqError(E_SCHEMA)
    for token in services:
        if not isinstance(token, str):
            raise ReqError(E_SCHEMA)
        if not _scalar_ok(token):
            raise ReqError(E_SCHEMA)
        if token == "":
            raise ReqError(E_SCHEMA)
    if len(set(services)) != len(services):
        raise ReqError(E_SCHEMA)
    ctx.alphabet = list(services)
    for position, token in enumerate(ctx.alphabet):
        ctx.index[token] = position

    rules = request["rules"]
    if not isinstance(rules, list):
        raise ReqError(E_SCHEMA)
    for rule in rules:
        if not isinstance(rule, dict):
            raise ReqError(E_SCHEMA)
        if set(rule.keys()) != set(["action", "when"]):
            raise ReqError(E_SCHEMA)
        action = rule["action"]
        if not isinstance(action, str) or (action != "allow" and action != "drop"):
            raise ReqError(E_SCHEMA)
        expression = _compile_expression(rule["when"], ctx)
        ctx.rules.append((action, expression))

    queries = request["queries"]
    if not isinstance(queries, list):
        raise ReqError(E_SCHEMA)
    for query in queries:
        if not isinstance(query, list):
            raise ReqError(E_SCHEMA)
        indices = []
        for token in query:
            if not isinstance(token, str):
                raise ReqError(E_SCHEMA)
            if not _scalar_ok(token):
                raise ReqError(E_SCHEMA)
            position = ctx.index.get(token)
            if position is None:
                raise ReqError(E_SCHEMA)
            indices.append(position)
        ctx.query_tokens += len(indices)
        ctx.queries.append(indices)

    return ctx


def _check_limits(ctx):
    """Declared size limits; violations are E_LIMIT."""
    if len(ctx.alphabet) > MAX_SERVICES:
        raise ReqError(E_LIMIT)
    for token in ctx.alphabet:
        if len(token) > MAX_SERVICE_CHARS:
            raise ReqError(E_LIMIT)
    if len(ctx.rules) > MAX_RULES:
        raise ReqError(E_LIMIT)
    if ctx.nodes > MAX_EXPR_NODES:
        raise ReqError(E_LIMIT)
    if ctx.max_args > MAX_ARGS:
        raise ReqError(E_LIMIT)
    if ctx.max_path > MAX_ATOM_PATH:
        raise ReqError(E_LIMIT)
    if len(ctx.atoms) > MAX_ATOMS:
        raise ReqError(E_LIMIT)
    if len(ctx.queries) > MAX_QUERIES:
        raise ReqError(E_LIMIT)
    for query in ctx.queries:
        if len(query) > MAX_QUERY_TOKENS:
            raise ReqError(E_LIMIT)
    if ctx.query_tokens > MAX_QUERY_TOTAL:
        raise ReqError(E_LIMIT)


# ---------------------------------------------------------------- monitors


def _prefix_function(pattern):
    """KMP failure function over a token pattern."""
    size = len(pattern)
    table = [0] * size
    for position in range(1, size):
        shift = table[position - 1]
        while shift > 0 and pattern[position] != pattern[shift]:
            shift = table[shift - 1]
        if pattern[position] == pattern[shift]:
            shift += 1
        table[position] = shift
    return table


def _monitor(op, pattern, alphabet):
    """Build one atomic monitor.

    Returns (number of states, transition table, set of true states) where
    transition[state][symbol] is the successor state.
    """
    size = len(pattern)
    width = len(alphabet)

    if op == "match":
        states = size + 2
        table = []
        for state in range(size + 1):
            row = []
            for symbol in range(width):
                if state < size and pattern[state] == alphabet[symbol]:
                    row.append(state + 1)
                else:
                    row.append(size + 1)
            table.append(row)
        table.append([size + 1] * width)
        return states, table, frozenset((size,))

    if op == "startswith":
        states = size + 1
        table = []
        for state in range(size + 1):
            row = []
            for symbol in range(width):
                if state < size:
                    if pattern[state] == alphabet[symbol]:
                        row.append(state + 1)
                    else:
                        row.append(0)
                else:
                    row.append(size)
            table.append(row)
        return states, table, frozenset((size,))

    failure = _prefix_function(pattern)
    table = []
    for state in range(size + 1):
        row = []
        for symbol in range(width):
            token = alphabet[symbol]
            shift = state
            while True:
                if shift < size and pattern[shift] == token:
                    row.append(shift + 1)
                    break
                if shift == 0:
                    row.append(0)
                    break
                shift = failure[shift - 1]
        table.append(row)

    if op == "endswith":
        return size + 1, table, frozenset((size,))

    # contains: the true state is absorbing
    table[size] = [size] * width
    return size + 1, table, frozenset((size,))


def _build_product(monitors, width):
    """Synchronous product of the monitors; returns (states, transitions)."""
    tables = [monitor[1] for monitor in monitors]
    start = tuple([0] * len(tables))
    states = [start]
    lookup = {start: 0}
    transitions = []
    queue = deque((0,))
    while queue:
        current = queue.popleft()
        component = states[current]
        if tables:
            rows = [table[value] for table, value in zip(tables, component)]
            successors = zip(*rows)
        else:
            successors = [(0,)] * width
        row = []
        for successor in successors:
            target = lookup.get(successor)
            if target is None:
                target = len(states)
                if target >= MAX_PRODUCT_STATES:
                    raise ReqError(E_COMPLEXITY)
                lookup[successor] = target
                states.append(successor)
                queue.append(target)
            row.append(target)
        transitions.append(row)
    return states, transitions


# --------------------------------------------------------------- evaluation


def _atom_masks(states, monitors):
    """Bit mask (over product states) of where each atom holds."""
    masks = []
    total = len(states)
    for position, monitor in enumerate(monitors):
        true_states = monitor[2]
        buffer = bytearray((total + 7) // 8)
        for index, component in enumerate(states):
            if component[position] in true_states:
                buffer[index >> 3] |= 1 << (index & 7)
        masks.append(int.from_bytes(bytes(buffer), "little"))
    return masks


def _evaluate(expression, masks, full):
    """Evaluate a compiled expression over sets of states (bit masks)."""
    kind = expression[0]
    if kind == "const":
        return full if expression[1] else 0
    if kind == "atom":
        return masks[expression[1]]
    if kind == "not":
        return (~_evaluate(expression[1], masks, full)) & full
    if kind == "and":
        result = full
        for child in expression[1]:
            result &= _evaluate(child, masks, full)
            if result == 0:
                break
        return result
    if kind == "or":
        result = 0
        for child in expression[1]:
            result |= _evaluate(child, masks, full)
            if result == full:
                break
        return result
    raise ReqError(E_SCHEMA)


# ------------------------------------------------------------- minimisation


def _minimise(transitions, accepting, width):
    """Hopcroft partition refinement; returns (block_of, block_count)."""
    total = len(transitions)
    yes = []
    no = []
    for state in range(total):
        if accepting[state]:
            yes.append(state)
        else:
            no.append(state)
    blocks = []
    if yes:
        blocks.append(yes)
    if no:
        blocks.append(no)
    block_of = [0] * total
    for number, block in enumerate(blocks):
        for state in block:
            block_of[state] = number

    inverse = []
    for symbol in range(width):
        table = {}
        for state in range(total):
            target = transitions[state][symbol]
            bucket = table.get(target)
            if bucket is None:
                table[target] = [state]
            else:
                bucket.append(state)
        inverse.append(table)

    queued = [False] * len(blocks)
    work = []
    for number in range(len(blocks)):
        work.append(number)
        queued[number] = True

    while work:
        splitter = work.pop()
        queued[splitter] = False
        members = blocks[splitter]
        for symbol in range(width):
            table = inverse[symbol]
            touched = {}
            for target in members:
                bucket = table.get(target)
                if bucket:
                    for state in bucket:
                        number = block_of[state]
                        group = touched.get(number)
                        if group is None:
                            touched[number] = [state]
                        else:
                            group.append(state)
            if not touched:
                continue
            for number, group in touched.items():
                block = blocks[number]
                if len(group) == len(block):
                    continue
                inside = set(group)
                outside = [state for state in block if state not in inside]
                if queued[number]:
                    blocks[number] = group
                    for state in group:
                        block_of[state] = number
                    fresh = len(blocks)
                    blocks.append(outside)
                    for state in outside:
                        block_of[state] = fresh
                    work.append(number)
                    queued[number] = True
                    work.append(fresh)
                    queued[fresh] = True
                elif len(group) <= len(outside):
                    blocks[number] = group
                    for state in group:
                        block_of[state] = number
                    fresh = len(blocks)
                    blocks.append(outside)
                    for state in outside:
                        block_of[state] = fresh
                    work.append(number)
                    queued[number] = True
                else:
                    blocks[number] = outside
                    for state in outside:
                        block_of[state] = number
                    fresh = len(blocks)
                    blocks.append(group)
                    for state in group:
                        block_of[state] = fresh
                    work.append(fresh)
                    queued[fresh] = True

    return block_of, len(blocks)


def _canonical(transitions, accepting, width):
    """Minimise, then renumber states by breadth-first traversal."""
    block_of, count = _minimise(transitions, accepting, width)
    block_rows = [None] * count
    for state in range(len(transitions)):
        block = block_of[state]
        if block_rows[block] is None:
            block_rows[block] = transitions[state]
    start = block_of[0]
    number = {start: 0}
    order = [start]
    queue = deque((start,))
    while queue:
        block = queue.popleft()
        row = block_rows[block]
        for symbol in range(width):
            target = block_of[row[symbol]]
            if target not in number:
                number[target] = len(number)
                order.append(target)
                queue.append(target)
    new_rows = []
    new_accept = []
    for block in order:
        row = block_rows[block]
        new_rows.append([number[block_of[row[symbol]]] for symbol in range(width)])
        new_accept.append(accepting[block_rows[block][0]])
    return new_rows, new_accept


def _distances(rows, accepting):
    """Minimum number of extra tokens reaching an accepting state."""
    total = len(rows)
    reverse = [[] for _ in range(total)]
    for state in range(total):
        for target in rows[state]:
            reverse[target].append(state)
    distance = [None] * total
    queue = deque()
    for state in range(total):
        if accepting[state]:
            distance[state] = 0
            queue.append(state)
    while queue:
        state = queue.popleft()
        step = distance[state] + 1
        for source in reverse[state]:
            if distance[source] is None:
                distance[source] = step
                queue.append(source)
    return distance


# --------------------------------------------------------------- compiler


def compile_bundle(request):
    """Compile one request into the canonical DFA plus query answers."""
    ctx = _validate(request)
    _check_limits(ctx)

    alphabet = ctx.alphabet
    width = len(alphabet)
    monitors = [_monitor(op, list(path), alphabet) for op, path in ctx.atoms]

    states, transitions = _build_product(monitors, width)

    masks = _atom_masks(states, monitors)
    full = (1 << len(states)) - 1
    allow_mask = 0
    drop_mask = 0
    for action, expression in ctx.rules:
        value = _evaluate(expression, masks, full)
        if action == "allow":
            allow_mask |= value
        else:
            drop_mask |= value
    accept_mask = allow_mask & (~drop_mask) & full

    accepting = [bool((accept_mask >> index) & 1) for index in range(len(states))]

    rows, accept = _canonical(transitions, accepting, width)
    distance = _distances(rows, accept)

    answers = []
    for query in ctx.queries:
        state = 0
        for symbol in query:
            state = rows[state][symbol]
        answers.append({"state": state, "allow": accept[state],
                        "distance": distance[state]})

    return {
        "ok": True,
        "dfa": {
            "start": 0,
            "accept": accept,
            "next": rows,
            "distance": distance,
        },
        "queries": answers,
    }


# ------------------------------------------------------------------- entry


def _handle_line(raw):
    """Process one physical input line."""
    if len(raw) > MAX_LINE_BYTES:
        return {"ok": False, "error": E_LIMIT}
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return {"ok": False, "error": E_JSON}
    if not _depth_ok(text):
        return {"ok": False, "error": E_LIMIT}
    try:
        request = json.loads(text, object_pairs_hook=_object_pairs,
                             parse_constant=_reject_constant)
    except Exception:
        return {"ok": False, "error": E_JSON}
    try:
        return compile_bundle(request)
    except ReqError as error:
        return {"ok": False, "error": error.code}


def main():
    data = sys.stdin.buffer.read()
    out = sys.stdout
    if data:
        lines = data.split(b"\n")
        if lines and lines[-1] == b"":
            lines.pop()
        for raw in lines:
            out.write(json.dumps(_handle_line(raw), separators=(",", ":")))
            out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
